def _session_clock(bars):
    """(open_min, close_min, step_min) for the regular session, measured from
    the tape's own volume profile so it is correct in either DST, on any
    timeframe, and on symbols whose feed carries no extended hours."""
    vol = {}
    for b in bars:
        s = str(b["t"])
        m = int(s[11:13]) * 60 + int(s[14:16])
        vol.setdefault(m, []).append(float(b.get("v") or 0))
    slots = sorted(vol)
    ns = len(slots)
    if ns < 4:
        return (slots[0] if slots else 0), (slots[-1] if slots else 0), 5
    gaps = {}
    for k in range(ns - 1):
        g = slots[k + 1] - slots[k]
        gaps[g] = gaps.get(g, 0) + 1
    step = max(gaps, key=gaps.get) or 5
    med = []
    for s in slots:
        v = sorted(vol[s])
        m = len(v)
        med.append(v[m // 2] if m % 2 else 0.5 * (v[m // 2 - 1] + v[m // 2]))
    w = max(1, int(round(15.0 / step)))
    if ns <= 2 * w + 1 or (slots[-1] - slots[0]) <= 400:
        return slots[0], slots[-1], step
    best = None
    bj = w
    for k in range(w, ns - w + 1):
        f = sum(med[k:k + w]) / w
        p = sum(med[k - w:k]) / w
        r = (f + 1.0) / (p + 1.0)
        if best is None or r > best:
            best = r
            bj = k
    lo = max(1, bj - w)
    hi = min(ns - 1, bj + w)
    bj = max(range(lo, hi + 1), key=lambda k: (med[k] + 1.0) / (med[k - 1] + 1.0))
    o = slots[bj]
    return o, min(slots[-1], o + 390 - step), step


def _median(v):
    v = sorted(v)
    m = len(v)
    if not m:
        return None
    return v[m // 2] if m % 2 else 0.5 * (v[m // 2 - 1] + v[m // 2])


def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    tt = [str(b["t"]) for b in bars]
    slot = [int(s[11:13]) * 60 + int(s[14:16]) for s in tt]
    day = [s[:10] for s in tt]
    o_min, c_min, step = _session_clock(bars)

    # ---- D_s : the median range of THIS time-of-day slot over the previous
    #      `slot_lb` sessions. The table is frozen at each session open, so a
    #      bar is only ever scaled by sessions that finished before it.
    lb = max(2, int(ctx.p.slot_lb))
    need = max(2, int(ctx.p.min_sess))
    hist = {}
    pend = {}
    cur = {}
    Dv = [None] * n
    for i in range(n):
        if i == 0 or day[i] != day[i - 1]:
            for s, r in pend.items():
                hist.setdefault(s, []).append(r)
            pend = {}
            cur = {}
            for s, lst in hist.items():
                if len(lst) >= need:
                    cur[s] = _median(lst[-lb:])
        pend[slot[i]] = float(bars[i]["h"]) - float(bars[i]["l"])
        Dv[i] = cur.get(slot[i])

    t0 = o_min + float(ctx.p.t_open)
    t1 = c_min - float(ctx.p.t_close)
    ctx.D = ctx.series(Dv, "diurnal_unit")
    ctx.win = ctx.series([1 if t0 <= slot[i] <= t1 else 0 for i in range(n)],
                         "in_window")
    ctx.eod = ctx.series([1 if slot[i] >= c_min - step else 0 for i in range(n)],
                         "session_end")
    ctx.dc = ctx.indicator("donchian", period=max(2, int(ctx.p.brk)))


def signal(ctx, i):
    if not ctx.win[i]:
        return 0
    d = ctx.D[i]
    if d is None or d <= 0:
        return 0
    u, l = ctx.dc.upper[i - 1], ctx.dc.lower[i - 1]
    if u is None or l is None:
        return 0
    c = ctx.c[i]
    b = float(ctx.p.buf) * d
    if c > u + b:
        return 1
    if c < l - b:
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    if ctx.eod[i]:
        return True
    d = ctx.D[i]
    if d is None or d <= 0:
        return False
    p = ctx.positions[0]
    e = max(0, int(p["entry_i"]))
    px = ctx.c[i]
    stop = float(ctx.p.stop_d) * d
    tgt = float(ctx.p.tp_d) * d
    if p["side"] == "long":
        best = p["entry"]
        for k in range(e, i + 1):
            v = ctx.c[k]
            if v > best:
                best = v
        if px >= p["entry"] + tgt:
            return True
        return px <= best - stop
    best = p["entry"]
    for k in range(e, i + 1):
        v = ctx.c[k]
        if v < best:
            best = v
    if px <= p["entry"] - tgt:
        return True
    return px >= best + stop
